-- Scratch saves generated by the supplied National Dex Gen 3 0.5.1 loader,
-- then reopened in a fresh 1025Dex process. No user saves are read or written.
local S=require('App').getState()
local SD=require('src.core.SaveData')
local Gen=require('Gen')
local P=require('src.core.game3.pokemon')
local Items=require('src.core.game3.items_data')
local MonOps=require('MonOps')
assert(#S.mods:status().errors==0,'registry load errors')
local function read(relative) return assert(loadfile(referenceRoot..'/'..relative))() end
local Source=read('src/species.lua')
local payload=Source.loadPayload(read)
assert(#payload==639,'unexpected source species count')
local sourceItems=read('data/items.lua')
if gen3both then
 local peer=assert(S.mods.exports.national_dex_gen3)
 assert(peer.isActive()==false and peer.provider()=='1025dex','source mod did not defer to 1025Dex')
 print('PASS both mods enabled; National Dex Gen3 defers to 1025Dex',version)
end
if gen3source then
 -- Reproduce Game3's post-loader native binding and game.ready boundary.
 -- App is only the headless loader harness; its editor bootstrap omits this.
 local live={data=S.data,mods=S.mods}
 require('src.mods.Gen3Compat').applyMerged(live)
 P.install(nil)
 S.mods.events:emit('game.ready',{game=live})
 local loaded={};for _,row in ipairs(S.mods:status().loaded)do loaded[row.id]=true end
 assert(loaded.national_dex_gen3 and not loaded['1025dex'],'fixture must be generated using source mod alone')
 local save=Gen.newGame(version);Gen.ensureBoxes(save)
 save.compatAllMons={};save.compatSourceItems={};save.party={}
 for _,r in ipairs(payload)do
  assert(P.speciesFromName(r.id)==r.slot,'source registry slot mismatch '..r.id)
  local mon=MonOps.create(S.data,r.id,35,3)
  assert(mon.species==r.slot,'source creation failed '..r.id)
  mon.nickname='SOURCE';mon.ot='OTHER';mon.otId=54321
  save.compatAllMons[#save.compatAllMons+1]=mon
  if #save.party<6 then save.party[#save.party+1]=mon end
 end
 for i,r in ipairs(sourceItems)do
  local info=Items.info(r.index)
  assert(info and info.name==r.name,'source numeric item registration failed '..r.id)
  local mon=MonOps.create(S.data,'EEVEE',35,3);mon.item=r.index;mon.heldItem=r.index
  save.compatSourceItems[i]={id=r.id,index=r.index,mon=mon}
 end
 save.storage.boxes[1].mons[30]=save.compatAllMons[#save.compatAllMons]
 local f=assert(io.open(fixturePath,'wb'));f:write(SD.encode(save));f:close()
 print('PASS National Dex Gen3 source scratch save',version,#save.compatAllMons,#sourceItems)
 return
end
assert(S.save.compatAllMons and #S.save.compatAllMons==639,'source scratch save not reopened')
for i,r in ipairs(payload)do
 local mon=S.save.compatAllMons[i]
 assert(mon.species==r.slot and P.speciesFromName(r.id)==r.slot and P.national(mon.species)==r.dex,'species identity changed '..r.id)
 local before=SD.encode({mon.species,mon.nickname,mon.otId,mon.moves,mon.pp,mon.personality,mon.ivs,mon.evs})
 Gen.hydrateMon(S.data,mon)
 assert(before==SD.encode({mon.species,mon.nickname,mon.otId,mon.moves,mon.pp,mon.personality,mon.ivs,mon.evs}),'source identity or moves changed '..r.id)
end
print('PASS all 639 source species, nickname/OT/moves/personality/IVs/EVs preserved',version)
local problems={}
for _,r in ipairs(S.save.compatSourceItems)do
 local info=Items.info(r.index)
 if not info or info.name:upper():gsub('[^A-Z0-9]','')~=r.id:gsub('_','') then problems[#problems+1]=r.id..' ('..r.index..')' end
end
print('SOURCE ITEM ISSUES',#problems,table.concat(problems,', '))
assert(#problems==0,'source evolution items cannot be recognized after switching mods')
assert(Items.toNumericId('SWEET_APPLE')==1002 and Items.toNumericId('TART_APPLE')==1001,'existing apple IDs changed')
for _,r in ipairs(sourceItems)do
 local id=r.id=='SWEET_APPLE' and 1002 or r.id=='TART_APPLE' and 1001 or r.index
 assert(Items.toNumericId(r.id)==id,'canonical item name cannot be resolved '..r.id)
end
local applin=MonOps.create(S.data,'APPLIN',20,3)
local Evolution=require('src.core.game3.evolution')
assert(Evolution.itemTarget(applin,910)==P.speciesFromName('APPLETUN'),'source Sweet Apple cannot evolve Applin')
assert(Evolution.itemTarget(applin,911)==P.speciesFromName('FLAPPLE'),'source Tart Apple cannot evolve Applin')
local Bag=require('src.core.game3.bag')
local bag=Bag.new()
for i,r in ipairs(sourceItems)do assert(Bag.add(bag,r.index,i),'source bag item rejected '..r.id) end
bag=assert(SD.decode(SD.encode({bag=bag}))).bag
Bag.migrate(bag)
for i,r in ipairs(sourceItems)do assert(Bag.get(bag,r.index)==i,'source bag quantity or ID changed '..r.id) end
assert(Bag.add(bag,1002,3) and Bag.get(bag,910)==11 and Bag.get(bag,1002)==3,'old and new apple stacks collided')
assert(Bag.remove(bag,910,1) and Bag.get(bag,910)==10 and Bag.get(bag,1002)==3,'old apple consumption altered new stack')
Items.installPack(require('src.mods.Merge').deepCopy(Items._pack))
for _,r in ipairs(sourceItems)do assert(Items.info(r.index),'source item lost after native item pack reload') end
assert(Items.toNumericId('SWEET_APPLE')==1002 and Items.toNumericId('TART_APPLE')==1001,'reload changed canonical apple IDs')
print('PASS native bag serialization/migration/quantities, separate old/new apple stacks and item-pack reload',version)
local pc=S.save.storage.boxes[1].mons[30]
assert(pc and pc.species==1089,'native PC lost source dex #1025')
local Copy=require('src.mods.Merge').deepCopy
local C=assert(loadfile(dexRoot..'/../Hoennto/campaign.lua'))()
local R=assert(loadfile(dexRoot..'/../Hoennto/roster.lua'))()(C,function()return {data=S.data}end)
C.roster=R
local mod={find=function()return {exports={transfer=R}}end}
assert(loadfile(dexRoot..'/compat/hoennto.lua'))()(mod)
local raw=Copy(S.save)
raw.storage.boxes={};raw.party={}
local list={};for _,m in ipairs(S.save.compatAllMons)do list[#list+1]=m end
for _,entry in ipairs(S.save.compatSourceItems)do list[#list+1]=entry.mon end
for i,m in ipairs(list)do
 local copy=Copy(m)
 if i<=6 then raw.party[i]=copy
 else local n=i-7;local b=math.floor(n/30)+1
  raw.storage.boxes[b]=raw.storage.boxes[b] or {mons={}}
  raw.storage.boxes[b].mons[n%30+1]=copy
 end
end
local state=C.capture(raw)
assert(#state.collection.records==658,'Hoennto source collection incomplete')
for _,record in ipairs(state.collection.records)do
 for _,target in ipairs({'firered','leafgreen','ruby','sapphire','emerald'})do
  local mon,reason=R.convert(record,target)
  assert(mon,'Hoennto rejected source mon '..record.species..' '..tostring(reason))
  assert(P.national(mon.species)==P.national(record.mon.species),'Hoennto changed species')
  assert(mon.nickname==record.mon.nickname and mon.otId==record.mon.otId,'Hoennto changed nickname/OT')
 end
end
R.project(raw,state)
assert(state.reserveCount==0,'compatible source mons left in reserve')
local total=#raw.party;for _,box in ipairs(raw.storage.boxes)do for _ in pairs(box.mons)do total=total+1 end end
assert(total==658,'Hoennto projection lost source mons')
print('PASS Hoennto all source species/items convert to five Gen3 targets; all 658 mons projected',version)
-- WildFollowers uses National identity only for art; native battle IDs remain
-- untouched. Exercise the actual adapter/form/sprite selection with source mons.
local wm={path=dexRoot..'/../WildFollowersRewrite',game={data=S.data},
 options={get=function(_,key)return key:find('sprites') and 'ee' end},
 assets={image=function(_,path)
  -- Headless image fixture: source geometry is read from the actual PNG IHDR.
  local f=assert(io.open(dexRoot..'/../WildFollowersRewrite/'..path,'rb'));local bytes=f:read(24);f:close()
  local function u32(at)local a,b,c,d=bytes:byte(at,at+3);return ((a*256+b)*256+c)*256+d end
  local w,h=u32(17),u32(21)
  return {setFilter=function()end,getDimensions=function()return w,h end}
 end},find=function()return {exports=S.mods.exports['1025dex']}end}
local includes={}
local function include(name)
 if not includes[name] then includes[name]=assert(loadfile(wm.path..'/src/'..name..'.lua'))()(wm,include) end
 return includes[name]
end
local sprites=include('sprites')
for _,set in ipairs({'ee','g9'})do
 wm.options.get=function(_,key)return key:find('sprites') and set end
 for _,mon in ipairs(S.save.compatAllMons)do
  local national=P.national(mon.species)
  local actor={species=mon.species,national=national,mon=mon,follower=true}
  assert(sprites:get(national,actor),'WildFollowers '..set..' art missing for source species '..national)
 end
end
print('PASS WildFollowers EE and G9RP art resolve for all 639 source species',version)
